## Типизация функций

**1. Типизация параметров:**
```typescript
function greet(name: string, age: number): string {
  return `Hello, ${name}! You are ${age} years old.`
}

// Стрелочная функция
const greet2 = (name: string, age: number): string => {
  return `Hello, ${name}!`
}
```

**2. Опциональные параметры:**
```typescript
function greet(name: string, greeting?: string): string {
  const msg = greeting ?? "Hello"
  return `${msg}, ${name}!`
}

greet("John")              // ✅
greet("John", "Hi")        // ✅
// greet("John", "Hi", "!")  // ❌ Ошибка: слишком много аргументов
```

**3. Параметры по умолчанию:**
```typescript
function greet(name: string, greeting: string = "Hello"): string {
  return `${greeting}, ${name}!`
}

greet("John")        // "Hello, John!"
greet("John", "Hi")  // "Hi, John!"
```

**4. Rest параметры:**
```typescript
function sum(...numbers: number[]): number {
  return numbers.reduce((acc, n) => acc + n, 0)
}

sum(1, 2, 3)        // 6
sum(1, 2, 3, 4, 5)  // 15
```

**5. Тип функции (function type):**
```typescript
// Синтаксис 1
type MathOperation = (a: number, b: number) => number

const add: MathOperation = (a, b) => a + b
const multiply: MathOperation = (a, b) => a * b

// Синтаксис 2 (interface)
interface MathOperation {
  (a: number, b: number): number
}

const add: MathOperation = (a, b) => a + b
```

**6. Callback функции:**
```typescript
function fetchData(
  url: string,
  onSuccess: (data: User[]) => void,
  onError: (error: Error) => void
) {
  fetch(url)
    .then(response => response.json())
    .then(data => onSuccess(data))
    .catch(error => onError(error))
}

fetchData(
  "/api/users",
  (users) => console.log(users),
  (error) => console.error(error)
)
```

**7. Возврат void:**
```typescript
function log(message: string): void {
  console.log(message)
  // ничего не возвращает
}

// void не значит "нельзя возвращать"
function logAndReturn(message: string): void {
  console.log(message)
  return  // ✅ можно, но значение игнорируется
}
```

**8. Never (функция никогда не завершается):**
```typescript
function throwError(message: string): never {
  throw new Error(message)
}

function infiniteLoop(): never {
  while (true) {
    // бесконечный цикл
  }
}
```

